CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lowercase account name used in URLs and in chat. Immutable in practice; the display name is what people change.
	"login" VARCHAR(25) NOT NULL UNIQUE,
	-- Cased or localised form of the login, e.g. a Japanese display name over a latin login.
	"display_name" VARCHAR(25) NOT NULL,
	-- Login identity and payout contact.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Bits bought and not yet cheered. A prepaid balance, so it is an integer count and never a float currency.
	"bit_balance" INTEGER NOT NULL DEFAULT 0,
	-- Partner status, which unlocks subscription tiers above the base one and changes the revenue split.
	"is_partner" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person. Everyone who watches has a row; a subset also broadcast, and those get a channels row too.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."login" IS 'Lowercase account name used in URLs and in chat. Immutable in practice; the display name is what people change.';
COMMENT ON COLUMN "users"."display_name" IS 'Cased or localised form of the login, e.g. a Japanese display name over a latin login.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and payout contact.';
COMMENT ON COLUMN "users"."bit_balance" IS 'Bits bought and not yet cheered. A prepaid balance, so it is an integer count and never a float currency.';
COMMENT ON COLUMN "users"."is_partner" IS 'Partner status, which unlocks subscription tiers above the base one and changes the revenue split.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "channels" (
	-- Owning account. The primary key is the user id, which makes the one-to-one explicit and lets every channel-scoped table key on the same value.
	"user_id" BIGINT,
	-- Stream title for the current or next broadcast. Overwritten constantly; the historical value is snapshotted on streams.
	"title" VARCHAR(140),
	-- Category the channel is currently set to. Null when never configured.
	"category_id" BIGINT,
	-- Denormalised follower tally, read on every channel page load.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Content warning gate shown before playback starts.
	"is_mature" BOOLEAN NOT NULL DEFAULT false,
	-- Minimum seconds between messages per chatter. Zero means off. A channel setting rather than a moderation action because it applies to everyone.
	"chat_slow_seconds" SMALLINT NOT NULL DEFAULT 0,
	-- Restricts chat to subscribers, a blunt but common anti-raid measure.
	"subscribers_only_chat" BOOLEAN NOT NULL DEFAULT false,
	-- When broadcasting was first enabled.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id")
);

COMMENT ON TABLE "channels" IS 'The broadcasting side of an account. It carries only current settings; everything about what actually happened lives on streams.';
COMMENT ON COLUMN "channels"."user_id" IS 'Owning account. The primary key is the user id, which makes the one-to-one explicit and lets every channel-scoped table key on the same value.';
COMMENT ON COLUMN "channels"."title" IS 'Stream title for the current or next broadcast. Overwritten constantly; the historical value is snapshotted on streams.';
COMMENT ON COLUMN "channels"."category_id" IS 'Category the channel is currently set to. Null when never configured.';
COMMENT ON COLUMN "channels"."follower_count" IS 'Denormalised follower tally, read on every channel page load.';
COMMENT ON COLUMN "channels"."is_mature" IS 'Content warning gate shown before playback starts.';
COMMENT ON COLUMN "channels"."chat_slow_seconds" IS 'Minimum seconds between messages per chatter. Zero means off. A channel setting rather than a moderation action because it applies to everyone.';
COMMENT ON COLUMN "channels"."subscribers_only_chat" IS 'Restricts chat to subscribers, a blunt but common anti-raid measure.';
COMMENT ON COLUMN "channels"."created_at" IS 'When broadcasting was first enabled.';

CREATE TABLE IF NOT EXISTS "categories" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Game or category name, e.g. "Just Chatting" or a game title. Unique, because directory browsing keys on it.
	"name" VARCHAR(160) NOT NULL UNIQUE,
	-- URL segment for the directory page.
	"slug" VARCHAR(180) NOT NULL UNIQUE,
	-- Object key of the cover image.
	"box_art_key" VARCHAR(200),
	-- False for non-game categories like Just Chatting or Music, which are directory entries with no release data behind them.
	"is_game" BOOLEAN NOT NULL DEFAULT true,
	-- Cached live viewers across all streams in the category. Recomputed on a short interval; it powers directory ranking and is never read for correctness.
	"viewer_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "categories" IS 'What is being streamed. A shared dimension rather than a string on the stream, so the directory, recommendations and the clip browser all agree on one identifier.';
COMMENT ON COLUMN "categories"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "categories"."name" IS 'Game or category name, e.g. "Just Chatting" or a game title. Unique, because directory browsing keys on it.';
COMMENT ON COLUMN "categories"."slug" IS 'URL segment for the directory page.';
COMMENT ON COLUMN "categories"."box_art_key" IS 'Object key of the cover image.';
COMMENT ON COLUMN "categories"."is_game" IS 'False for non-game categories like Just Chatting or Music, which are directory entries with no release data behind them.';
COMMENT ON COLUMN "categories"."viewer_count" IS 'Cached live viewers across all streams in the category. Recomputed on a short interval; it powers directory ranking and is never read for correctness.';

CREATE TABLE IF NOT EXISTS "streams" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Broadcasting channel.
	"channel_user_id" BIGINT NOT NULL,
	-- Title snapshot at go-live. Snapshotted because the channel title is overwritten before the next broadcast and the VOD still needs its own name.
	"title" VARCHAR(140) NOT NULL,
	-- Go-live instant.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- End instant. Null means live right now - which is the only definition of live the schema needs, and it cannot go stale the way an is_live boolean does.
	"ended_at" TIMESTAMPTZ,
	-- Highest concurrent viewers observed, written by the sampler during the broadcast.
	"peak_viewers" INTEGER NOT NULL DEFAULT 0,
	-- Mean concurrents over the session, finalised when the stream ends. The number that actually matters to sponsors.
	"average_viewers" INTEGER NOT NULL DEFAULT 0,
	-- BCP 47 broadcast language, used by directory filters.
	"language" VARCHAR(8) NOT NULL DEFAULT 'en',
	-- Whether a VOD was captured. False when the broadcaster disabled archiving or rights forced it off.
	"was_recorded" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "streams" IS 'One broadcast session, and the spine of the whole schema. VODs, clips, chat and cheers all attach to a session, which is what makes "how did that stream go" a single query.';
COMMENT ON COLUMN "streams"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "streams"."channel_user_id" IS 'Broadcasting channel.';
COMMENT ON COLUMN "streams"."title" IS 'Title snapshot at go-live. Snapshotted because the channel title is overwritten before the next broadcast and the VOD still needs its own name.';
COMMENT ON COLUMN "streams"."started_at" IS 'Go-live instant.';
COMMENT ON COLUMN "streams"."ended_at" IS 'End instant. Null means live right now - which is the only definition of live the schema needs, and it cannot go stale the way an is_live boolean does.';
COMMENT ON COLUMN "streams"."peak_viewers" IS 'Highest concurrent viewers observed, written by the sampler during the broadcast.';
COMMENT ON COLUMN "streams"."average_viewers" IS 'Mean concurrents over the session, finalised when the stream ends. The number that actually matters to sponsors.';
COMMENT ON COLUMN "streams"."language" IS 'BCP 47 broadcast language, used by directory filters.';
COMMENT ON COLUMN "streams"."was_recorded" IS 'Whether a VOD was captured. False when the broadcaster disabled archiving or rights forced it off.';

CREATE INDEX "idx_streams_channel_started"
ON "streams" ("channel_user_id", "started_at");
CREATE INDEX "idx_streams_live"
ON "streams" ("ended_at");

CREATE TABLE IF NOT EXISTS "stream_category_segments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Session the segment belongs to.
	"stream_id" BIGINT NOT NULL,
	-- What was being played during the segment.
	"category_id" BIGINT NOT NULL,
	-- When the broadcaster switched to this category.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- When they switched away. Null for the segment still running.
	"ended_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "stream_category_segments" IS 'A broadcaster changes game mid-session constantly. Segments make that a time range rather than an overwritten column, so a clip can be attributed to the category that was live when it was taken.';
COMMENT ON COLUMN "stream_category_segments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "stream_category_segments"."stream_id" IS 'Session the segment belongs to.';
COMMENT ON COLUMN "stream_category_segments"."category_id" IS 'What was being played during the segment.';
COMMENT ON COLUMN "stream_category_segments"."started_at" IS 'When the broadcaster switched to this category.';
COMMENT ON COLUMN "stream_category_segments"."ended_at" IS 'When they switched away. Null for the segment still running.';

CREATE INDEX "idx_segments_stream_time"
ON "stream_category_segments" ("stream_id", "started_at");
CREATE INDEX "idx_segments_category_time"
ON "stream_category_segments" ("category_id", "started_at");

CREATE TABLE IF NOT EXISTS "vods" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Session this recording is of. Unique - one session produces at most one VOD, which is why this is a one-to-one rather than a table of arbitrary videos.
	"stream_id" BIGINT NOT NULL UNIQUE,
	-- Recording length. Usually shorter than the session when muted or rights-struck segments are cut.
	"duration_seconds" INTEGER NOT NULL,
	-- Object storage key of the recording manifest.
	"storage_key" VARCHAR(300) NOT NULL,
	-- Replay views, counted separately from live viewers - they measure completely different things.
	"view_count" INTEGER NOT NULL DEFAULT 0,
	-- When the recording is deleted under the retention policy, which varies by account type. Null for permanently retained highlights.
	"expires_at" TIMESTAMPTZ,
	-- True when audio was muted somewhere for a copyright match; surfaced in the UI so the broadcaster is not surprised.
	"is_muted_segments" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "vods" IS 'The replay of a session. Deriving it from streams rather than storing it as a standalone video keeps chat replay, clips and analytics anchored to the same timeline.';
COMMENT ON COLUMN "vods"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "vods"."stream_id" IS 'Session this recording is of. Unique - one session produces at most one VOD, which is why this is a one-to-one rather than a table of arbitrary videos.';
COMMENT ON COLUMN "vods"."duration_seconds" IS 'Recording length. Usually shorter than the session when muted or rights-struck segments are cut.';
COMMENT ON COLUMN "vods"."storage_key" IS 'Object storage key of the recording manifest.';
COMMENT ON COLUMN "vods"."view_count" IS 'Replay views, counted separately from live viewers - they measure completely different things.';
COMMENT ON COLUMN "vods"."expires_at" IS 'When the recording is deleted under the retention policy, which varies by account type. Null for permanently retained highlights.';
COMMENT ON COLUMN "vods"."is_muted_segments" IS 'True when audio was muted somewhere for a copyright match; surfaced in the UI so the broadcaster is not surprised.';

CREATE TABLE IF NOT EXISTS "clips" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Shareable URL token. Random rather than sequential, because clip URLs are pasted publicly and should not be enumerable.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Session the clip came from. Kept even when the VOD has expired, so attribution survives retention.
	"stream_id" BIGINT NOT NULL,
	-- Source recording. Null once the VOD expires - the clip outlives it, which is the whole point of clipping.
	"vod_id" BIGINT,
	-- Who made the clip. Null if that account is deleted; the clip stays up.
	"creator_user_id" BIGINT,
	-- Clip title, typed by the clipper.
	"title" VARCHAR(140) NOT NULL,
	-- Start offset within the session timeline, which is why a clip can be re-cut from the VOD if needed.
	"offset_seconds" INTEGER NOT NULL,
	-- Clip length, capped by product rules at a minute or so.
	"duration_seconds" SMALLINT NOT NULL,
	-- Clip views. Clips are the main discovery surface, so this drives a lot of ranking.
	"view_count" INTEGER NOT NULL DEFAULT 0,
	-- When the clip was taken.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "clips" IS 'A short excerpt anchored to a session timeline rather than an independent upload. It survives the VOD expiring, which is why stream_id is not null while vod_id is.';
COMMENT ON COLUMN "clips"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "clips"."slug" IS 'Shareable URL token. Random rather than sequential, because clip URLs are pasted publicly and should not be enumerable.';
COMMENT ON COLUMN "clips"."stream_id" IS 'Session the clip came from. Kept even when the VOD has expired, so attribution survives retention.';
COMMENT ON COLUMN "clips"."vod_id" IS 'Source recording. Null once the VOD expires - the clip outlives it, which is the whole point of clipping.';
COMMENT ON COLUMN "clips"."creator_user_id" IS 'Who made the clip. Null if that account is deleted; the clip stays up.';
COMMENT ON COLUMN "clips"."title" IS 'Clip title, typed by the clipper.';
COMMENT ON COLUMN "clips"."offset_seconds" IS 'Start offset within the session timeline, which is why a clip can be re-cut from the VOD if needed.';
COMMENT ON COLUMN "clips"."duration_seconds" IS 'Clip length, capped by product rules at a minute or so.';
COMMENT ON COLUMN "clips"."view_count" IS 'Clip views. Clips are the main discovery surface, so this drives a lot of ranking.';
COMMENT ON COLUMN "clips"."created_at" IS 'When the clip was taken.';

CREATE INDEX "idx_clips_stream_offset"
ON "clips" ("stream_id", "offset_seconds");
CREATE INDEX "idx_clips_creator_time"
ON "clips" ("creator_user_id", "created_at");

CREATE TABLE IF NOT EXISTS "channel_subscriptions" (
	-- Surrogate primary key. Not a (channel, subscriber) key, because the same pair recurs over years and every term must stay on record.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel being subscribed to.
	"channel_user_id" BIGINT NOT NULL,
	-- Account receiving the benefits.
	"subscriber_user_id" BIGINT NOT NULL,
	-- Who paid, when the sub was a gift. Null for a self-purchased sub. This single nullable column is the whole gifted-sub model.
	"gifter_user_id" BIGINT,
	-- 1000 | 2000 | 3000 | prime. Tier decides price, emote slots and the revenue split.
	"tier" VARCHAR(8) NOT NULL DEFAULT '1000',
	-- Amount charged in minor units, snapshotted so a later price change does not rewrite past terms.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency of price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Consecutive months, shown as a badge in chat. Reset by a lapse, which is why it is stored rather than derived from dates.
	"streak_months" SMALLINT NOT NULL DEFAULT 1,
	-- Start of this term.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- End of the paid term. Benefits last until this instant even after cancellation.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- False for gifted subs and for cancelled ones, which look identical from here on.
	"auto_renew" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "channel_subscriptions" IS 'One row per paid term, appended rather than updated. Active subscribers are the rows whose ends_at is in the future, so a lapsed and resubscribed viewer keeps a complete history.';
COMMENT ON COLUMN "channel_subscriptions"."id" IS 'Surrogate primary key. Not a (channel, subscriber) key, because the same pair recurs over years and every term must stay on record.';
COMMENT ON COLUMN "channel_subscriptions"."channel_user_id" IS 'Channel being subscribed to.';
COMMENT ON COLUMN "channel_subscriptions"."subscriber_user_id" IS 'Account receiving the benefits.';
COMMENT ON COLUMN "channel_subscriptions"."gifter_user_id" IS 'Who paid, when the sub was a gift. Null for a self-purchased sub. This single nullable column is the whole gifted-sub model.';
COMMENT ON COLUMN "channel_subscriptions"."tier" IS '1000 | 2000 | 3000 | prime. Tier decides price, emote slots and the revenue split.';
COMMENT ON COLUMN "channel_subscriptions"."price_cents" IS 'Amount charged in minor units, snapshotted so a later price change does not rewrite past terms.';
COMMENT ON COLUMN "channel_subscriptions"."currency_code" IS 'ISO 4217 currency of price_cents.';
COMMENT ON COLUMN "channel_subscriptions"."streak_months" IS 'Consecutive months, shown as a badge in chat. Reset by a lapse, which is why it is stored rather than derived from dates.';
COMMENT ON COLUMN "channel_subscriptions"."started_at" IS 'Start of this term.';
COMMENT ON COLUMN "channel_subscriptions"."ends_at" IS 'End of the paid term. Benefits last until this instant even after cancellation.';
COMMENT ON COLUMN "channel_subscriptions"."auto_renew" IS 'False for gifted subs and for cancelled ones, which look identical from here on.';

CREATE INDEX "idx_subs_channel_active"
ON "channel_subscriptions" ("channel_user_id", "ends_at");
CREATE INDEX "idx_subs_user_active"
ON "channel_subscriptions" ("subscriber_user_id", "ends_at");
CREATE INDEX "idx_subs_gifter"
ON "channel_subscriptions" ("gifter_user_id", "started_at");

CREATE TABLE IF NOT EXISTS "cheers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel receiving the bits.
	"channel_user_id" BIGINT NOT NULL,
	-- Session during which it was cheered. Null when cheered on an offline channel page, which is allowed and pays out the same.
	"stream_id" BIGINT,
	-- Cheerer. Null once the account is deleted; the payout record must survive the user.
	"user_id" BIGINT,
	-- Bits spent. A count of prepaid units, not money - the cash conversion happened when the bits were bought.
	"bits" INTEGER NOT NULL,
	-- Attached chat message. Null for a bare cheer.
	"message" VARCHAR(500),
	-- Hides the cheerer in the UI. The user_id stays for payouts and abuse handling, which is why this is a flag and not a null.
	"is_anonymous" BOOLEAN NOT NULL DEFAULT false,
	-- Cheer instant.
	"cheered_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cheers" IS 'Append-only bit spend. It doubles as the revenue ledger for a broadcast, which is why rows are never edited and never deleted with the user.';
COMMENT ON COLUMN "cheers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cheers"."channel_user_id" IS 'Channel receiving the bits.';
COMMENT ON COLUMN "cheers"."stream_id" IS 'Session during which it was cheered. Null when cheered on an offline channel page, which is allowed and pays out the same.';
COMMENT ON COLUMN "cheers"."user_id" IS 'Cheerer. Null once the account is deleted; the payout record must survive the user.';
COMMENT ON COLUMN "cheers"."bits" IS 'Bits spent. A count of prepaid units, not money - the cash conversion happened when the bits were bought.';
COMMENT ON COLUMN "cheers"."message" IS 'Attached chat message. Null for a bare cheer.';
COMMENT ON COLUMN "cheers"."is_anonymous" IS 'Hides the cheerer in the UI. The user_id stays for payouts and abuse handling, which is why this is a flag and not a null.';
COMMENT ON COLUMN "cheers"."cheered_at" IS 'Cheer instant.';

CREATE INDEX "idx_cheers_channel_time"
ON "cheers" ("channel_user_id", "cheered_at");
CREATE INDEX "idx_cheers_stream_time"
ON "cheers" ("stream_id", "cheered_at");

CREATE TABLE IF NOT EXISTS "chat_messages" (
	-- Surrogate primary key, monotonic so chat replay pages by id without a tiebreaker.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel the message was sent in.
	"channel_user_id" BIGINT NOT NULL,
	-- Session in progress at the time. Null for messages sent while offline, and what makes chat replay on a VOD a simple range query.
	"stream_id" BIGINT,
	-- Author. Null once the account is deleted; the message is redacted rather than removed so the thread still reads.
	"user_id" BIGINT,
	-- Message text, emote codes included as written.
	"body" VARCHAR(500) NOT NULL,
	-- Send instant. Chat replay is a scan of this column within the session window.
	"sent_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Set when a moderator removes the message. Soft-deleted so moderation can be audited and reversed.
	"deleted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "chat_messages" IS 'The highest-volume table by far, and range-partitioned by month in practice. It is written by chat and read almost entirely by VOD replay, which is why the stream id is denormalised onto every row.';
COMMENT ON COLUMN "chat_messages"."id" IS 'Surrogate primary key, monotonic so chat replay pages by id without a tiebreaker.';
COMMENT ON COLUMN "chat_messages"."channel_user_id" IS 'Channel the message was sent in.';
COMMENT ON COLUMN "chat_messages"."stream_id" IS 'Session in progress at the time. Null for messages sent while offline, and what makes chat replay on a VOD a simple range query.';
COMMENT ON COLUMN "chat_messages"."user_id" IS 'Author. Null once the account is deleted; the message is redacted rather than removed so the thread still reads.';
COMMENT ON COLUMN "chat_messages"."body" IS 'Message text, emote codes included as written.';
COMMENT ON COLUMN "chat_messages"."sent_at" IS 'Send instant. Chat replay is a scan of this column within the session window.';
COMMENT ON COLUMN "chat_messages"."deleted_at" IS 'Set when a moderator removes the message. Soft-deleted so moderation can be audited and reversed.';

CREATE INDEX "idx_chat_channel_time"
ON "chat_messages" ("channel_user_id", "sent_at");
CREATE INDEX "idx_chat_stream_time"
ON "chat_messages" ("stream_id", "sent_at");

CREATE TABLE IF NOT EXISTS "moderation_actions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel where the action was taken.
	"channel_user_id" BIGINT NOT NULL,
	-- Viewer being actioned.
	"target_user_id" BIGINT NOT NULL,
	-- Moderator responsible. Null for an automated filter action, which is exactly the distinction an audit needs.
	"moderator_user_id" BIGINT,
	-- timeout | ban | unban | delete_message | mod | unmod.
	"action" VARCHAR(24) NOT NULL,
	-- Message that triggered the action, when there was one.
	"message_id" BIGINT,
	-- Timeout length. Null for a permanent ban - a null here and a very large number are not the same thing to the UI.
	"duration_seconds" INTEGER,
	-- Moderator note, visible to other moderators.
	"reason" VARCHAR(300),
	-- When the action was taken.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "moderation_actions" IS 'An append-only moderation log. Current ban state is derived from the latest row per target rather than stored, so an unban is a new row and the history stays intact.';
COMMENT ON COLUMN "moderation_actions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "moderation_actions"."channel_user_id" IS 'Channel where the action was taken.';
COMMENT ON COLUMN "moderation_actions"."target_user_id" IS 'Viewer being actioned.';
COMMENT ON COLUMN "moderation_actions"."moderator_user_id" IS 'Moderator responsible. Null for an automated filter action, which is exactly the distinction an audit needs.';
COMMENT ON COLUMN "moderation_actions"."action" IS 'timeout | ban | unban | delete_message | mod | unmod.';
COMMENT ON COLUMN "moderation_actions"."message_id" IS 'Message that triggered the action, when there was one.';
COMMENT ON COLUMN "moderation_actions"."duration_seconds" IS 'Timeout length. Null for a permanent ban - a null here and a very large number are not the same thing to the UI.';
COMMENT ON COLUMN "moderation_actions"."reason" IS 'Moderator note, visible to other moderators.';
COMMENT ON COLUMN "moderation_actions"."created_at" IS 'When the action was taken.';

CREATE INDEX "idx_mod_channel_target"
ON "moderation_actions" ("channel_user_id", "target_user_id", "created_at");

CREATE TABLE IF NOT EXISTS "raids" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Session that sent the raid. Always a live session, since a raid happens at the end of a broadcast.
	"from_stream_id" BIGINT NOT NULL,
	-- Channel receiving the viewers.
	"to_channel_user_id" BIGINT NOT NULL,
	-- Viewers carried over, snapshotted at execution. The whole social value of a raid is this number, so it is recorded rather than recomputed.
	"viewer_count" INTEGER NOT NULL,
	-- When the raid executed, after the countdown and any cancellation.
	"raided_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "raids" IS 'A handoff of an audience between channels. Recording it is what makes raid-driven follows attributable and what lets the receiving channel apply raid-specific chat rules.';
COMMENT ON COLUMN "raids"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "raids"."from_stream_id" IS 'Session that sent the raid. Always a live session, since a raid happens at the end of a broadcast.';
COMMENT ON COLUMN "raids"."to_channel_user_id" IS 'Channel receiving the viewers.';
COMMENT ON COLUMN "raids"."viewer_count" IS 'Viewers carried over, snapshotted at execution. The whole social value of a raid is this number, so it is recorded rather than recomputed.';
COMMENT ON COLUMN "raids"."raided_at" IS 'When the raid executed, after the countdown and any cancellation.';

CREATE INDEX "idx_raids_target_time"
ON "raids" ("to_channel_user_id", "raided_at");

ALTER TABLE "channels"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "channels"
ADD FOREIGN KEY("category_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "streams"
ADD FOREIGN KEY("channel_user_id") REFERENCES "channels"("user_id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "stream_category_segments"
ADD FOREIGN KEY("stream_id") REFERENCES "streams"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "stream_category_segments"
ADD FOREIGN KEY("category_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "vods"
ADD FOREIGN KEY("stream_id") REFERENCES "streams"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
